import importlib.util
from pathlib import Path

# The script sits in the project root, outside the package.
spec = importlib.util.spec_from_file_location(
    "regen_release_deps", Path(__file__).parent.parent / "regen_release_deps.py"
)
rrd = importlib.util.module_from_spec(spec)
spec.loader.exec_module(rrd)


EXPORT = """\
# This file was autogenerated by uv via the following command:
#    uv export --frozen --no-dev --no-emit-project --no-hashes
nicegui==3.18.0
    # via quote-builder
pygobject==3.58.1
    # via quote-builder
pycairo==1.29.2
    # via pygobject
pyobjc-framework-cocoa==12.2.2 ; sys_platform == 'darwin'
    # via pywebview
"""

PYPROJECT = """\
[project]
name = "quote-builder"
version = "2026.11.20.5+dev"
requires-python = ">=3.13"
dependencies = [
    "nicegui[native]>=3.18.0",
    "pygobject>=3.58.1",
]

[project.scripts]
quote-builder = "quote_builder.app:main"

[build-system]
requires = ["uv_build>=0.12.17,<0.13.0"]
build-backend = "uv_build"

[dependency-groups]
dev = [
    "pytest>=9.1.1",
]
"""


def fake_export(monkeypatch, output):
    """Make exported_pins read `output` instead of running uv."""

    class Done:
        stdout = output

    monkeypatch.setattr(rrd.subprocess, "run", lambda *a, **k: Done())


def test_exported_pins_drops_comments_and_sorts(monkeypatch):
    fake_export(monkeypatch, EXPORT)
    assert rrd.exported_pins(Path(".")) == [
        "nicegui==3.18.0",
        "pycairo==1.29.2",
        "pygobject==3.58.1",
        "pyobjc-framework-cocoa==12.2.2 ; sys_platform == 'darwin'",
    ]


def test_pin_name_reads_through_markers_and_operators():
    assert rrd.pin_name("nicegui==3.18.0") == "nicegui"
    assert rrd.pin_name("pygobject>=3.58.1") == "pygobject"
    assert rrd.pin_name("pyobjc-core==12.2.2 ; sys_platform == 'darwin'") == "pyobjc-core"


def test_floored_keeps_native_bindings_floating():
    pins = ["nicegui==3.18.0", "pycairo==1.29.2", "pygobject==3.58.1"]
    assert rrd.floored(pins) == ["nicegui==3.18.0", "pycairo>=1.29.2", "pygobject>=3.58.1"]


def test_release_pins_floors_the_closure(monkeypatch):
    monkeypatch.setattr(rrd, "exported_pins", lambda cwd: ["nicegui==3.18.0", "pygobject==3.58.1"])
    assert rrd.release_pins(Path(".")) == ["nicegui==3.18.0", "pygobject>=3.58.1"]


def test_normalized_ignores_case_and_spaces():
    assert rrd.normalized(["NiceGUI == 3.18.0"]) == rrd.normalized(["nicegui==3.18.0"])


def test_dependencies_block_is_quoted_and_indented():
    assert rrd.dependencies_block(["a==1", "b==2"]) == (
        'dependencies = [\n    "a==1",\n    "b==2",\n]'
    )


def test_pins_match_compares_project_to_the_floored_lock(monkeypatch):
    monkeypatch.setattr(rrd, "exported_pins", lambda cwd: ["nicegui==3.18.0", "pygobject==3.58.1"])
    monkeypatch.setattr(
        rrd, "project_dependencies", lambda cwd: ["nicegui==3.18.0", "pygobject>=3.58.1"]
    )
    assert rrd.pins_match(Path("."))
    # A bare `==` on the native binding doesn't match the floored expectation.
    monkeypatch.setattr(
        rrd, "project_dependencies", lambda cwd: ["nicegui==3.18.0", "pygobject==3.58.1"]
    )
    assert not rrd.pins_match(Path("."))


def test_write_dependencies_rewrites_only_the_project_block(monkeypatch, tmp_path):
    (tmp_path / "pyproject.toml").write_text(PYPROJECT)
    monkeypatch.setattr(
        rrd, "exported_pins", lambda cwd: ["nicegui==3.18.0", "pycairo==1.29.2", "pygobject==3.58.1"]
    )
    locks = []
    monkeypatch.setattr(rrd.subprocess, "run", lambda *a, **k: locks.append(a))
    assert rrd.write_dependencies(tmp_path) is True
    text = (tmp_path / "pyproject.toml").read_text()
    assert (
        'dependencies = [\n    "nicegui==3.18.0",\n    "pycairo>=1.29.2",\n'
        '    "pygobject>=3.58.1",\n]'
    ) in text
    # The dev group and build requires are left alone.
    assert 'dev = [\n    "pytest>=9.1.1",\n]' in text
    assert 'requires = ["uv_build>=0.12.17,<0.13.0"]' in text
    # It reconciles the lock afterward.
    assert locks and locks[0][0][:2] == ["uv", "lock"]


def test_write_dependencies_no_op_when_already_pinned(monkeypatch, tmp_path):
    (tmp_path / "pyproject.toml").write_text(
        PYPROJECT.replace(
            '    "nicegui[native]>=3.18.0",\n    "pygobject>=3.58.1",\n',
            '    "nicegui==3.18.0",\n    "pygobject>=3.58.1",\n',
        )
    )
    monkeypatch.setattr(rrd, "exported_pins", lambda cwd: ["nicegui==3.18.0", "pygobject==3.58.1"])
    ran = []
    monkeypatch.setattr(rrd.subprocess, "run", lambda *a, **k: ran.append(a))
    assert rrd.write_dependencies(tmp_path) is False
    assert ran == []  # no re-lock when nothing changed
